  1→'use client';
  2→
  3→import React, { useState } from 'react';
  4→import Link from 'next/link';
  5→import { useRouter } from 'next/navigation';
  6→import { Button } from '@/components/ui/button';
  7→import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/card';
  8→import { Input } from '@/components/ui/input';
  9→import { Label } from '@/components/ui/label';
 10→import { Loader2, Eye, EyeOff, AlertCircle } from 'lucide-react';
 11→import { apiClient } from '@/lib/api/client';
 12→import { useAuthStore } from '@/lib/store/auth';
 13→
 14→interface LoginFormData {
 15→  email: string;
 16→  password: string;
 17→}
 18→
 19→export default function LoginPage() {
 20→  const router = useRouter();
 21→  const [formData, setFormData] = useState<LoginFormData>({
 22→    email: '',
 23→    password: '',
 24→  });
 25→  const [showPassword, setShowPassword] = useState(false);
 26→  const [isLoading, setIsLoading] = useState(false);
 27→  const [error, setError] = useState<string | null>(null);
 28→
 29→  const { setUser, setToken } = useAuthStore();
 30→
 31→  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 32→    const { name, value } = e.target;
 33→    setFormData(prev => ({
 34→      ...prev,
 35→      [name]: value,
 36→    }));
 37→    // Clear error when user starts typing
 38→    if (error) setError(null);
 39→  };
 40→
 41→  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
 42→    e.preventDefault();
 43→    setIsLoading(true);
 44→    setError(null);
 45→
 46→    try {
 47→      // Create form data for the backend API
 48→      const loginData = new FormData();
 49→      loginData.append('username', formData.email);
 50→      loginData.append('password', formData.password);
 51→
 52→      const response = await fetch('http://localhost:8000/api/v1/auth/login', {
 53→        method: 'POST',
 54→        body: loginData,
 55→      });
 56→
 57→      if (!response.ok) {
 58→        const errorData = await response.json();
 59→        throw new Error(errorData.detail || 'Login failed');
 60→      }
 61→
 62→      const authData = await response.json();
 63→      
 64→      // Store tokens and user info
 65→      setToken(authData.access_token);
 66→      localStorage.setItem('refresh_token', authData.refresh_token);
 67→      
 68→      // Get current user info
 69→      const userResponse = await apiClient.get('/v1/auth/me');
 70→      setUser(userResponse);
 71→
 72→      // Redirect to dashboard
 73→      router.push('/dashboard');
 74→    } catch (error) {
 75→      setError(error instanceof Error ? error.message : 'Login failed');
 76→    } finally {
 77→      setIsLoading(false);
 78→    }
 79→  };
 80→
 81→  return (
 82→    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 px-4">
 83→      <Card className="w-full max-w-md">
 84→        <CardHeader className="text-center">
 85→          <CardTitle className="text-2xl font-bold">Welcome Back</CardTitle>
 86→          <CardDescription>
 87→            Sign in to your PKM account to continue
 88→          </CardDescription>
 89→        </CardHeader>
 90→        <CardContent>
 91→          <form onSubmit={handleSubmit} className="space-y-4">
 92→            {error && (
 93→              <div className="flex items-center gap-2 p-3 text-sm text-red-700 bg-red-50 border border-red-200 rounded-md">
 94→                <AlertCircle className="h-4 w-4" />
 95→                {error}
 96→              </div>
 97→            )}
 98→
 99→            <div className="space-y-2">
100→              <Label htmlFor="email">Email</Label>
101→              <Input
102→                id="email"
103→                name="email"
104→                type="email"
105→                placeholder="Enter your email"
106→                value={formData.email}
107→                onChange={handleInputChange}
108→                required
109→                disabled={isLoading}
110→              />
111→            </div>
112→
113→            <div className="space-y-2">
114→              <Label htmlFor="password">Password</Label>
115→              <div className="relative">
116→                <Input
117→                  id="password"
118→                  name="password"
119→                  type={showPassword ? 'text' : 'password'}
120→                  placeholder="Enter your password"
121→                  value={formData.password}
122→                  onChange={handleInputChange}
123→                  required
124→                  disabled={isLoading}
125→                />
126→                <Button
127→                  type="button"
128→                  variant="ghost"
129→                  size="sm"
130→                  className="absolute right-2 top-1/2 transform -translate-y-1/2 h-auto p-1"
131→                  onClick={() => setShowPassword(!showPassword)}
132→                  disabled={isLoading}
133→                >
134→                  {showPassword ? (
135→                    <EyeOff className="h-4 w-4" />
136→                  ) : (
137→                    <Eye className="h-4 w-4" />
138→                  )}
139→                </Button>
140→              </div>
141→            </div>
142→
143→            <div className="flex items-center justify-between text-sm">
144→              <Link
145→                href="/forgot-password"
146→                className="text-blue-600 hover:text-blue-500 hover:underline"
147→              >
148→                Forgot password?
149→              </Link>
150→            </div>
151→
152→            <Button
153→              type="submit"
154→              className="w-full"
155→              disabled={isLoading}
156→            >
157→              {isLoading ? (
158→                <>
159→                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
160→                  Signing In...
161→                </>
162→              ) : (
163→                'Sign In'
164→              )}
165→            </Button>
166→          </form>
167→
168→          <div className="mt-6 text-center text-sm">
169→            <span className="text-gray-600">Don't have an account? </span>
170→            <Link
171→              href="/register"
172→              className="text-blue-600 hover:text-blue-500 hover:underline font-medium"
173→            >
174→              Sign up
175→            </Link>
176→          </div>
177→        </CardContent>
178→      </Card>
179→    </div>
180→  );
181→}

  1→'use client';
  2→
  3→import React, { useState } from 'react';
  4→import Link from 'next/link';
  5→import { useRouter } from 'next/navigation';
  6→import { Button } from '@/components/ui/button';
  7→import { Card, CardHeader, CardTitle, CardContent, CardDescription } from '@/components/ui/card';
  8→import { Input } from '@/components/ui/input';
  9→import { Label } from '@/components/ui/label';
 10→import { Loader2, Eye, EyeOff, AlertCircle, CheckCircle } from 'lucide-react';
 11→
 12→interface RegisterFormData {
 13→  email: string;
 14→  full_name: string;
 15→  password: string;
 16→  confirmPassword: string;
 17→}
 18→
 19→interface ValidationErrors {
 20→  email?: string;
 21→  full_name?: string;
 22→  password?: string;
 23→  confirmPassword?: string;
 24→}
 25→
 26→export default function RegisterPage() {
 27→  const router = useRouter();
 28→  const [formData, setFormData] = useState<RegisterFormData>({
 29→    email: '',
 30→    full_name: '',
 31→    password: '',
 32→    confirmPassword: '',
 33→  });
 34→  const [showPassword, setShowPassword] = useState(false);
 35→  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
 36→  const [isLoading, setIsLoading] = useState(false);
 37→  const [error, setError] = useState<string | null>(null);
 38→  const [success, setSuccess] = useState<string | null>(null);
 39→  const [validationErrors, setValidationErrors] = useState<ValidationErrors>({});
 40→
 41→  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 42→    const { name, value } = e.target;
 43→    setFormData(prev => ({
 44→      ...prev,
 45→      [name]: value,
 46→    }));
 47→    // Clear errors when user starts typing
 48→    if (error) setError(null);
 49→    if (validationErrors[name as keyof ValidationErrors]) {
 50→      setValidationErrors(prev => ({
 51→        ...prev,
 52→        [name]: undefined,
 53→      }));
 54→    }
 55→  };
 56→
 57→  const validateForm = (): boolean => {
 58→    const errors: ValidationErrors = {};
 59→
 60→    // Email validation
 61→    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
 62→    if (!formData.email) {
 63→      errors.email = 'Email is required';
 64→    } else if (!emailRegex.test(formData.email)) {
 65→      errors.email = 'Please enter a valid email address';
 66→    }
 67→
 68→    // Full name validation
 69→    if (!formData.full_name.trim()) {
 70→      errors.full_name = 'Full name is required';
 71→    } else if (formData.full_name.trim().length < 2) {
 72→      errors.full_name = 'Full name must be at least 2 characters';
 73→    }
 74→
 75→    // Password validation
 76→    if (!formData.password) {
 77→      errors.password = 'Password is required';
 78→    } else if (formData.password.length < 8) {
 79→      errors.password = 'Password must be at least 8 characters';
 80→    } else if (!/(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/.test(formData.password)) {
 81→      errors.password = 'Password must contain at least one uppercase letter, one lowercase letter, and one number';
 82→    }
 83→
 84→    // Confirm password validation
 85→    if (!formData.confirmPassword) {
 86→      errors.confirmPassword = 'Please confirm your password';
 87→    } else if (formData.password !== formData.confirmPassword) {
 88→      errors.confirmPassword = 'Passwords do not match';
 89→    }
 90→
 91→    setValidationErrors(errors);
 92→    return Object.keys(errors).length === 0;
 93→  };
 94→
 95→  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
 96→    e.preventDefault();
 97→    
 98→    if (!validateForm()) {
 99→      return;
100→    }
101→
102→    setIsLoading(true);
103→    setError(null);
104→    setSuccess(null);
105→
106→    try {
107→      const response = await fetch('http://localhost:8000/api/v1/auth/register', {
108→        method: 'POST',
109→        headers: {
110→          'Content-Type': 'application/json',
111→        },
112→        body: JSON.stringify({
113→          email: formData.email,
114→          full_name: formData.full_name.trim(),
115→          password: formData.password,
116→        }),
117→      });
118→
119→      if (!response.ok) {
120→        const errorData = await response.json();
121→        throw new Error(errorData.detail || 'Registration failed');
122→      }
123→
124→      setSuccess('Account created successfully! You can now sign in.');
125→      
126→      // Redirect to login after successful registration
127→      setTimeout(() => {
128→        router.push('/login');
129→      }, 2000);
130→    } catch (error) {
131→      setError(error instanceof Error ? error.message : 'Registration failed');
132→    } finally {
133→      setIsLoading(false);
134→    }
135→  };
136→
137→  return (
138→    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-gray-50 to-gray-100 dark:from-gray-900 dark:to-gray-800 px-4 py-8">
139→      <Card className="w-full max-w-md">
140→        <CardHeader className="text-center">
141→          <CardTitle className="text-2xl font-bold">Create Account</CardTitle>
142→          <CardDescription>
143→            Join PKM to start organizing your knowledge
144→          </CardDescription>
145→        </CardHeader>
146→        <CardContent>
147→          <form onSubmit={handleSubmit} className="space-y-4">
148→            {error && (
149→              <div className="flex items-center gap-2 p-3 text-sm text-red-700 bg-red-50 border border-red-200 rounded-md">
150→                <AlertCircle className="h-4 w-4" />
151→                {error}
152→              </div>
153→            )}
154→
155→            {success && (
156→              <div className="flex items-center gap-2 p-3 text-sm text-green-700 bg-green-50 border border-green-200 rounded-md">
157→                <CheckCircle className="h-4 w-4" />
158→                {success}
159→              </div>
160→            )}
161→
162→            <div className="space-y-2">
163→              <Label htmlFor="full_name">Full Name</Label>
164→              <Input
165→                id="full_name"
166→                name="full_name"
167→                type="text"
168→                placeholder="Enter your full name"
169→                value={formData.full_name}
170→                onChange={handleInputChange}
171→                required
172→                disabled={isLoading}
173→                className={validationErrors.full_name ? 'border-red-500' : ''}
174→              />
175→              {validationErrors.full_name && (
176→                <p className="text-sm text-red-600">{validationErrors.full_name}</p>
177→              )}
178→            </div>
179→
180→            <div className="space-y-2">
181→              <Label htmlFor="email">Email</Label>
182→              <Input
183→                id="email"
184→                name="email"
185→                type="email"
186→                placeholder="Enter your email"
187→                value={formData.email}
188→                onChange={handleInputChange}
189→                required
190→                disabled={isLoading}
191→                className={validationErrors.email ? 'border-red-500' : ''}
192→              />
193→              {validationErrors.email && (
194→                <p className="text-sm text-red-600">{validationErrors.email}</p>
195→              )}
196→            </div>
197→
198→            <div className="space-y-2">
199→              <Label htmlFor="password">Password</Label>
200→              <div className="relative">
201→                <Input
202→                  id="password"
203→                  name="password"
204→                  type={showPassword ? 'text' : 'password'}
205→                  placeholder="Create a password"
206→                  value={formData.password}
207→                  onChange={handleInputChange}
208→                  required
209→                  disabled={isLoading}
210→                  className={validationErrors.password ? 'border-red-500' : ''}
211→                />
212→                <Button
213→                  type="button"
214→                  variant="ghost"
215→                  size="sm"
216→                  className="absolute right-2 top-1/2 transform -translate-y-1/2 h-auto p-1"
217→                  onClick={() => setShowPassword(!showPassword)}
218→                  disabled={isLoading}
219→                >
220→                  {showPassword ? (
221→                    <EyeOff className="h-4 w-4" />
222→                  ) : (
223→                    <Eye className="h-4 w-4" />
224→                  )}
225→                </Button>
226→              </div>
227→              {validationErrors.password && (
228→                <p className="text-sm text-red-600">{validationErrors.password}</p>
229→              )}
230→            </div>
231→
232→            <div className="space-y-2">
233→              <Label htmlFor="confirmPassword">Confirm Password</Label>
234→              <div className="relative">
235→                <Input
236→                  id="confirmPassword"
237→                  name="confirmPassword"
238→                  type={showConfirmPassword ? 'text' : 'password'}
239→                  placeholder="Confirm your password"
240→                  value={formData.confirmPassword}
241→                  onChange={handleInputChange}
242→                  required
243→                  disabled={isLoading}
244→                  className={validationErrors.confirmPassword ? 'border-red-500' : ''}
245→                />
246→                <Button
247→                  type="button"
248→                  variant="ghost"
249→                  size="sm"
250→                  className="absolute right-2 top-1/2 transform -translate-y-1/2 h-auto p-1"
251→                  onClick={() => setShowConfirmPassword(!showConfirmPassword)}
252→                  disabled={isLoading}
253→                >
254→                  {showConfirmPassword ? (
255→                    <EyeOff className="h-4 w-4" />
256→                  ) : (
257→                    <Eye className="h-4 w-4" />
258→                  )}
259→                </Button>
260→              </div>
261→              {validationErrors.confirmPassword && (
262→                <p className="text-sm text-red-600">{validationErrors.confirmPassword}</p>
263→              )}
264→            </div>
265→
266→            <Button
267→              type="submit"
268→              className="w-full"
269→              disabled={isLoading}
270→            >
271→              {isLoading ? (
272→                <>
273→                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
274→                  Creating Account...
275→                </>
276→              ) : (
277→                'Create Account'
278→              )}
279→            </Button>
280→          </form>
281→
282→          <div className="mt-6 text-center text-sm">
283→            <span className="text-gray-600">Already have an account? </span>
284→            <Link
285→              href="/login"
286→              className="text-blue-600 hover:text-blue-500 hover:underline font-medium"
287→            >
288→              Sign in
289→            </Link>
290→          </div>
291→        </CardContent>
292→      </Card>
293→    </div>
294→  );
295→}

