  5→interface AuthStore extends AuthState {
  6→  // Actions
  7→  login: (credentials: LoginCredentials) => Promise<void>;
  8→  logout: () => void;
  9→  setUser: (user: SessionUser) => void;
 10→  setToken: (token: string) => void;
 11→  clearError: () => void;
 12→  checkAuth: () => Promise<void>;
 13→}
 14→
 15→export const useAuthStore = create<AuthStore>()(
 16→  persist(
 17→    (set, get) => ({
 18→      // Initial state
 19→      user: null,
 20→      accessToken: null,
 21→      isAuthenticated: false,
 22→      isLoading: false,
 23→      error: null,
 24→
 25→      // Actions
 26→      login: async (credentials: LoginCredentials) => {
 27→        set({ isLoading: true, error: null });
 28→        
 29→        try {
 30→          // Create form data for OAuth2 login
 31→          const formData = new FormData();
 32→          formData.append('username', credentials.email);
 33→          formData.append('password', credentials.password);
 34→
 35→          const response = await fetch('http://localhost:8000/api/v1/auth/login', {
 36→            method: 'POST',
 37→            body: formData,
 38→          });
 39→
 40→          if (!response.ok) {
 41→            const errorData = await response.json();
 42→            throw new Error(errorData.detail || 'Login failed');
 43→          }
 44→
 45→          const authData = await response.json();
 46→          
 47→          // Store tokens
 48→          if (typeof window !== 'undefined') {
 49→            localStorage.setItem('access_token', authData.access_token);
 50→            localStorage.setItem('refresh_token', authData.refresh_token);
 51→          }
 52→
 53→          // Get user profile
 54→          const userResponse = await fetch('http://localhost:8000/api/v1/auth/me', {
 55→            headers: { Authorization: `Bearer ${authData.access_token}` },
 56→          });
 57→
 58→          if (!userResponse.ok) {
 59→            throw new Error('Failed to get user profile');
 60→          }
 61→
 62→          const userData = await userResponse.json();
 63→          
 64→          set({
 65→            user: userData,
 66→            accessToken: authData.access_token,
 67→            isAuthenticated: true,
 68→            isLoading: false,
 69→            error: null,
 70→          });
 71→        } catch (error) {
 72→          set({
 73→            isLoading: false,
 74→            error: error instanceof Error ? error.message : 'Login failed',
 75→          });
 76→          throw error;
 77→        }
 78→      },
 79→
 80→      logout: () => {
 81→        set({
 82→          user: null,
 83→          accessToken: null,
 84→          isAuthenticated: false,
 85→          error: null,
 86→        });
 87→
 88→        // Clear localStorage
 89→        if (typeof window !== 'undefined') {
 90→          localStorage.removeItem('access_token');
 91→          localStorage.removeItem('refresh_token');
 92→        }
 93→      },
 94→
 95→      setUser: (user: SessionUser) => {
 96→        set({ user, isAuthenticated: true });
 97→      },
 98→
 99→      setToken: (token: string) => {
100→        set({ accessToken: token });
101→        if (typeof window !== 'undefined') {
102→          localStorage.setItem('access_token', token);
103→        }
104→      },
105→
106→      clearError: () => {
107→        set({ error: null });
108→      },
109→
110→      checkAuth: async () => {
111→        const token = typeof window !== 'undefined' 
112→          ? localStorage.getItem('access_token') 
113→          : null;
114→
115→        if (!token) {
116→          set({ isAuthenticated: false, user: null, accessToken: null });
117→          return;
118→        }
119→
120→        set({ isLoading: true });
121→
122→        try {
123→          // Verify token with backend
124→          const response = await fetch('http://localhost:8000/api/v1/auth/me', {
125→            headers: { Authorization: `Bearer ${token}` },
126→          });
127→
128→          if (!response.ok) {
129→            throw new Error('Token invalid');
130→          }
131→
132→          const user: SessionUser = await response.json();
133→          
134→          set({
135→            user,
136→            accessToken: token,
137→            isAuthenticated: true,
138→            isLoading: false,
139→          });
140→        } catch {
141→          // Token is invalid, clear auth state
142→          get().logout();
143→          set({ isLoading: false });
144→        }
145→      },
146→    }),
147→    {
148→      name: 'auth-storage',
149→      partialize: (state) => ({
150→        user: state.user,
151→        accessToken: state.accessToken,
152→        isAuthenticated: state.isAuthenticated,
153→      }),
154→    }
155→  )
156→);

  1→import axios, { AxiosInstance, AxiosRequestConfig, AxiosResponse } from 'axios';
  2→import { ApiResponse, ApiError, RequestOptions } from '@/types/api';
  3→
  4→class ApiClient {
  5→  private instance: AxiosInstance;
  6→  private baseURL: string;
  7→
  8→  constructor(baseURL?: string) {
  9→    this.baseURL = baseURL || process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000/api';
 10→    
 11→    this.instance = axios.create({
 12→      baseURL: this.baseURL,
 13→      timeout: 10000,
 14→      headers: {
 15→        'Content-Type': 'application/json',
 16→      },
 17→    });
 18→
 19→    this.setupInterceptors();
 20→  }
 21→
 22→  private setupInterceptors(): void {
 23→    // Request interceptor
 24→    this.instance.interceptors.request.use(
 25→      (config) => {
 26→        // Add auth token if available
 27→        const token = this.getAuthToken();
 28→        if (token) {
 29→          config.headers.Authorization = `Bearer ${token}`;
 30→        }
 31→        return config;
 32→      },
 33→      (error) => Promise.reject(error)
 34→    );
 35→
 36→    // Response interceptor
 37→    this.instance.interceptors.response.use(
 38→      (response: AxiosResponse) => response,
 39→      async (error) => {
 40→        const originalRequest = error.config;
 41→
 42→        // Handle 401 unauthorized errors
 43→        if (error.response?.status === 401 && !originalRequest._retry) {
 44→          originalRequest._retry = true;
 45→          
 46→          try {
 47→            await this.refreshToken();
 48→            const token = this.getAuthToken();
 49→            if (token) {
 50→              originalRequest.headers.Authorization = `Bearer ${token}`;
 51→              return this.instance(originalRequest);
 52→            }
 53→          } catch (refreshError) {
 54→            // Redirect to login or handle auth failure
 55→            this.handleAuthFailure();
 56→            return Promise.reject(refreshError);
 57→          }
 58→        }
 59→
 60→        return Promise.reject(this.handleError(error));
 61→      }
 62→    );
 63→  }
 64→
 65→  private getAuthToken(): string | null {
 66→    // Get token from localStorage or session storage
 67→    if (typeof window !== 'undefined') {
 68→      return localStorage.getItem('access_token');
 69→    }
 70→    return null;
 71→  }
 72→
 73→  private async refreshToken(): Promise<void> {
 74→    const refreshToken = typeof window !== 'undefined' 
 75→      ? localStorage.getItem('refresh_token') 
 76→      : null;
 77→
 78→    if (!refreshToken) {
 79→      throw new Error('No refresh token available');
 80→    }
 81→
 82→    try {
 83→      const response = await axios.post(`${this.baseURL}/v1/auth/refresh`, {
 84→        refresh_token: refreshToken,
 85→      });
 86→
 87→      const { access_token, refresh_token: newRefreshToken } = response.data;
 88→      
 89→      if (typeof window !== 'undefined') {
 90→        localStorage.setItem('access_token', access_token);
 91→        if (newRefreshToken) {
 92→          localStorage.setItem('refresh_token', newRefreshToken);
 93→        }
 94→      }
 95→    } catch (error) {
 96→      // Clear tokens on refresh failure
 97→      if (typeof window !== 'undefined') {
 98→        localStorage.removeItem('access_token');
 99→        localStorage.removeItem('refresh_token');
100→      }
101→      throw error;
102→    }
103→  }
104→
105→  private handleAuthFailure(): void {
106→    // Clear tokens and redirect to login
107→    if (typeof window !== 'undefined') {
108→      localStorage.removeItem('access_token');
109→      localStorage.removeItem('refresh_token');
110→      window.location.href = '/login';
111→    }
112→  }
113→
114→  private handleError(error: unknown): ApiError {
115→    // Type guard for axios error structure
116→    const isAxiosError = (err: unknown): err is {
117→      response?: { status: number; data?: { message?: string; code?: string; details?: Record<string, unknown> } };
118→      request?: unknown;
119→      message?: string;
120→    } => {
121→      return typeof err === 'object' && err !== null;
122→    };
123→
124→    if (isAxiosError(error)) {
125→      if (error.response) {
126→        // Server responded with error status
127→        return {
128→          message: error.response.data?.message || error.message || 'Server error',
129→          status: error.response.status,
130→          code: error.response.data?.code,
131→          details: error.response.data?.details,
132→        };
133→      } else if (error.request) {
134→        // Request was made but no response received
135→        return {
136→          message: 'No response from server',
137→          status: 0,
138→          code: 'NETWORK_ERROR',
139→        };
140→      } else {
141→        // Something else happened
142→        return {
143→          message: error.message || 'Unknown error occurred',
144→          status: 0,
145→          code: 'UNKNOWN_ERROR',
146→        };
147→      }
148→    }
149→
150→    // Fallback for unknown error types
151→    return {
152→      message: 'Unknown error occurred',
153→      status: 0,
154→      code: 'UNKNOWN_ERROR',
155→    };
156→  }
157→
158→  // Generic HTTP methods
159→  async get<T>(url: string, options?: RequestOptions): Promise<ApiResponse<T>> {
160→    const config: AxiosRequestConfig = {
161→      ...options,
162→    };
163→    const response = await this.instance.get(url, config);
164→    return response.data;
165→  }
166→
167→  async post<T>(url: string, data?: unknown, options?: RequestOptions): Promise<ApiResponse<T>> {
168→    const config: AxiosRequestConfig = {
169→      ...options,
170→    };
171→    const response = await this.instance.post(url, data, config);
172→    return response.data;
173→  }
174→
175→  async put<T>(url: string, data?: unknown, options?: RequestOptions): Promise<ApiResponse<T>> {
176→    const config: AxiosRequestConfig = {
177→      ...options,
178→    };
179→    const response = await this.instance.put(url, data, config);
180→    return response.data;
181→  }
182→
183→  async patch<T>(url: string, data?: unknown, options?: RequestOptions): Promise<ApiResponse<T>> {
184→    const config: AxiosRequestConfig = {
185→      ...options,
186→    };
187→    const response = await this.instance.patch(url, data, config);
188→    return response.data;
189→  }
190→
191→  async delete<T>(url: string, options?: RequestOptions): Promise<ApiResponse<T>> {
192→    const config: AxiosRequestConfig = {
193→      ...options,
194→    };
195→    const response = await this.instance.delete(url, config);
196→    return response.data;
197→  }
198→
199→  // Set auth token manually
200→  setAuthToken(token: string): void {
201→    if (typeof window !== 'undefined') {
202→      localStorage.setItem('access_token', token);
203→    }
204→  }
205→
206→  // Clear auth token
207→  clearAuthToken(): void {
208→    if (typeof window !== 'undefined') {
209→      localStorage.removeItem('access_token');
210→      localStorage.removeItem('refresh_token');
211→    }
212→  }
213→}
214→
215→// Create singleton instance
216→export const apiClient = new ApiClient();
217→export default ApiClient;

