  9→interface TreeViewProps {
 10→  nodes: ProjectNode[];
 11→  onSelectNode?: (node: ProjectNode) => void;
 12→  onCreateChild?: (parentNode: ProjectNode) => void;
 13→  onEdit?: (node: ProjectNode) => void;
 14→  onDelete?: (node: ProjectNode) => void;
 15→  selectedNodeId?: string;
 16→  className?: string;
 17→}
 18→
 19→interface TreeNodeProps {
 20→  node: ProjectNode;
 21→  level: number;
 22→  onSelectNode?: (node: ProjectNode) => void;
 23→  onCreateChild?: (parentNode: ProjectNode) => void;
 24→  onEdit?: (node: ProjectNode) => void;
 25→  onDelete?: (node: ProjectNode) => void;
 26→  selectedNodeId?: string;
 27→  isExpanded: boolean;
 28→  onToggleExpanded: (nodeId: string) => void;
 29→}
 30→
 31→const TreeNode: React.FC<TreeNodeProps> = ({
 32→  node,
 33→  level,
 34→  onSelectNode,
 35→  onCreateChild,
 36→  onEdit,
 37→  onDelete,
 38→  selectedNodeId,
 39→  isExpanded,
