172→          ))}
173→        </div>
174→      )}
175→    </div>
176→  );
177→};
178→
179→export const TreeView: React.FC<TreeViewProps> = ({
180→  nodes,
181→  onSelectNode,
182→  onCreateChild,
183→  onEdit,
184→  onDelete,
185→  selectedNodeId,
186→  className = '',
187→}) => {
188→  const [expandedNodes, setExpandedNodes] = useState<Set<string>>(new Set());
189→
190→  const handleToggleExpanded = (nodeId: string) => {
191→    setExpandedNodes(prev => {
192→      const newSet = new Set(prev);
193→      if (newSet.has(nodeId)) {
194→        newSet.delete(nodeId);
195→      } else {
196→        newSet.add(nodeId);
197→      }
198→      return newSet;
199→    });
200→  };
201→
202→  if (nodes.length === 0) {
203→    return (
