205→        <div className="text-center text-gray-500 dark:text-gray-400">
206→          <Folder className="h-12 w-12 mx-auto mb-3 opacity-50" />
207→          <p className="text-sm">No projects found</p>
208→          <p className="text-xs mt-1">Create your first project to get started</p>
209→        </div>
210→      </Card>
211→    );
212→  }
213→
214→  return (
215→    <Card className={`p-4 ${className}`}>
216→      <div className="space-y-1">
217→        {nodes.map((node) => (
218→          <TreeNode
219→            key={node.id}
220→            node={node}
221→            level={0}
222→            onSelectNode={onSelectNode}
223→            onCreateChild={onCreateChild}
224→            onEdit={onEdit}
225→            onDelete={onDelete}
226→            selectedNodeId={selectedNodeId}
227→            isExpanded={expandedNodes.has(node.id)}
228→            onToggleExpanded={handleToggleExpanded}
229→          />
230→        ))}
231→      </div>
232→    </Card>
233→  );
234→};
235→
236→export default TreeView;
