'use client';

import React, { useState, useEffect, useRef } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Card, CardHeader, CardTitle, CardContent, CardFooter } from '@/components/ui/card';
import { 
  Bold, Italic, Underline, List, ListOrdered, Link2, 
  Save, X, Eye, Edit3, AlignLeft, AlignCenter, AlignRight,
  Heading1, Heading2, Heading3, Code, Quote, FileText
} from 'lucide-react';
import { Note, NoteCreate, NoteUpdate, NoteCreateSchema, NoteUpdateSchema } from '@/types/note';
import { Project } from '@/types/project';

interface NoteEditorProps {
  mode: 'create' | 'edit' | 'view';
  note?: Note;
  projects?: Project[];
  defaultProjectId?: string;
  onSave?: (data: NoteCreate | NoteUpdate) => void;
  onCancel?: () => void;
  onEdit?: () => void;
  isLoading?: boolean;
  className?: string;
}

interface ToolbarButtonProps {
  onClick: () => void;
  icon: React.ComponentType<{ className?: string }>;
  tooltip: string;
  isActive?: boolean;
  disabled?: boolean;
}

const ToolbarButton: React.FC<ToolbarButtonProps> = ({ 
  onClick, icon: Icon, tooltip, isActive = false, disabled = false 
}) => (
  <Button
    type="button"
    variant={isActive ? "default" : "ghost"}
    size="sm"
    onClick={onClick}
    title={tooltip}
    disabled={disabled}
    className="h-8 w-8 p-0"
  >
    <Icon className="h-4 w-4" />
  </Button>
);

export const NoteEditor: React.FC<NoteEditorProps> = ({
  mode,
  note,
  projects = [],
  defaultProjectId,
  onSave,
  onCancel,
  onEdit,
  isLoading = false,
  className = ''
}) => {
  const [isPreviewMode, setIsPreviewMode] = useState(mode === 'view');
  const [content, setContent] = useState(note?.content || '');
  const contentRef = useRef<HTMLTextAreaElement>(null);

  const schema = mode === 'create' ? NoteCreateSchema : NoteUpdateSchema;

  const {
    register,
    handleSubmit,
    setValue,
    watch,
    formState: { errors, isSubmitting, isDirty }
  } = useForm<NoteCreate | NoteUpdate>({
    resolver: zodResolver(schema),
    defaultValues: mode === 'edit' && note ? {
      title: note.title,
      content: note.content,
      note_type: note.note_type,
      project_id: note.project_id,
      keywords: note.keywords?.map(k => k.id) || []
    } : {
      title: '',
      content: '',
      note_type: 'text',
      project_id: defaultProjectId || '',
      keywords: []
    }
  });

  const watchedContent = watch('content');

  useEffect(() => {
    setContent(watchedContent || '');
  }, [watchedContent]);

  const insertTextAtCursor = (before: string, after: string = '') => {
    const textarea = contentRef.current;
    if (!textarea) return;

    const start = textarea.selectionStart;
    const end = textarea.selectionEnd;
    const selectedText = content.substring(start, end);
    const newText = before + selectedText + after;

    const newContent = content.substring(0, start) + newText + content.substring(end);
    setContent(newContent);
    setValue('content', newContent);

    // Set cursor position after the inserted text
    setTimeout(() => {
      textarea.focus();
      textarea.setSelectionRange(start + before.length, start + before.length + selectedText.length);
    }, 0);
  };

  const handleToolbarAction = (action: string) => {
    switch (action) {
      case 'bold':
        insertTextAtCursor('**', '**');
        break;
      case 'italic':
        insertTextAtCursor('*', '*');
        break;
      case 'underline':
        insertTextAtCursor('<u>', '</u>');
        break;
      case 'heading1':
        insertTextAtCursor('# ');
        break;
      case 'heading2':
        insertTextAtCursor('## ');
        break;
      case 'heading3':
        insertTextAtCursor('### ');
        break;
      case 'list':
        insertTextAtCursor('- ');
        break;
      case 'orderedList':
        insertTextAtCursor('1. ');
        break;
      case 'link':
        insertTextAtCursor('[', '](url)');
        break;
      case 'code':
        insertTextAtCursor('`', '`');
        break;
      case 'quote':
        insertTextAtCursor('> ');
        break;
      default:
        break;
    }
  };

  const formatMarkdownContent = (text: string): string => {
    return text
      .replace(/^### (.*$)/gim, '<h3>$1</h3>')
      .replace(/^## (.*$)/gim, '<h2>$1</h2>')
      .replace(/^# (.*$)/gim, '<h1>$1</h1>')
      .replace(/\*\*(.*)\*\*/gim, '<strong>$1</strong>')
      .replace(/\*(.*)\*/gim, '<em>$1</em>')
      .replace(/<u>(.*)<\/u>/gim, '<u>$1</u>')
      .replace(/`(.*)`/gim, '<code>$1</code>')
      .replace(/^> (.*$)/gim, '<blockquote>$1</blockquote>')
      .replace(/^- (.*$)/gim, '<li>$1</li>')
      .replace(/^\d+\. (.*$)/gim, '<li>$1</li>')
      .replace(/\[([^\]]+)\]\(([^)]+)\)/gim, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>')
      .replace(/\n/g, '<br>');
  };

  const handleFormSubmit = (data: NoteCreate | NoteUpdate) => {
    onSave?.(data);
  };

  const handleContentChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const newContent = e.target.value;
    setContent(newContent);
    setValue('content', newContent);
  };

  if (mode === 'view' && note) {
    return (
      <Card className={`w-full ${className}`}>
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-2xl">{note.title}</CardTitle>
            <div className="flex items-center gap-4 text-sm text-gray-500 mt-2">
              <span>Type: {note.note_type}</span>
              <span>Created: {new Date(note.created_at).toLocaleDateString()}</span>
              {note.updated_at !== note.created_at && (
                <span>Updated: {new Date(note.updated_at).toLocaleDateString()}</span>
              )}
            </div>
          </div>
          <Button onClick={onEdit} variant="outline">
            <Edit3 className="h-4 w-4 mr-2" />
            Edit
          </Button>
        </CardHeader>
        <CardContent>
          <div 
            className="prose max-w-none dark:prose-invert"
            dangerouslySetInnerHTML={{ __html: formatMarkdownContent(note.content) }}
          />
          {note.keywords && note.keywords.length > 0 && (
            <div className="mt-6 pt-4 border-t">
              <h4 className="text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">Keywords:</h4>
              <div className="flex flex-wrap gap-2">
                {note.keywords.map((keyword) => (
                  <span
                    key={keyword.id}
                    className="px-2 py-1 bg-blue-100 dark:bg-blue-900 text-blue-800 dark:text-blue-200 text-xs rounded-md"
                  >
                    {keyword.name}
                  </span>
                ))}
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={`w-full ${className}`}>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <FileText className="h-5 w-5" />
          {mode === 'create' ? 'Create New Note' : 'Edit Note'}
        </CardTitle>
      </CardHeader>

      <form onSubmit={handleSubmit(handleFormSubmit)}>
        <CardContent className="space-y-4">
          {/* Title */}
          <div className="space-y-2">
            <Label htmlFor="title">Title *</Label>
            <Input
              id="title"
              placeholder="Enter note title"
              {...register('title')}
              className={errors.title ? 'border-red-500' : ''}
            />
            {errors.title && (
              <p className="text-sm text-red-500">{errors.title.message}</p>
            )}
          </div>

          {/* Project Selection */}
          <div className="space-y-2">
            <Label htmlFor="project_id">Project *</Label>
            <Select
              value={watch('project_id') || ''}
              onValueChange={(value) => setValue('project_id', value)}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select a project" />
              </SelectTrigger>
              <SelectContent>
                {projects.map((project) => (
                  <SelectItem key={project.id} value={project.id}>
                    {project.name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
            {errors.project_id && (
              <p className="text-sm text-red-500">{errors.project_id.message}</p>
            )}
          </div>

          {/* Note Type */}
          <div className="space-y-2">
            <Label htmlFor="note_type">Note Type</Label>
            <Select
              value={watch('note_type') || 'text'}
              onValueChange={(value) => setValue('note_type', value as 'text' | 'markdown' | 'code' | 'meeting')}
            >
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="text">Text</SelectItem>
                <SelectItem value="markdown">Markdown</SelectItem>
                <SelectItem value="code">Code</SelectItem>
                <SelectItem value="meeting">Meeting Notes</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Content Editor */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <Label>Content *</Label>
              <div className="flex items-center gap-2">
                <Button
                  type="button"
                  variant={isPreviewMode ? "default" : "outline"}
                  size="sm"
                  onClick={() => setIsPreviewMode(!isPreviewMode)}
                >
                  <Eye className="h-4 w-4 mr-2" />
                  {isPreviewMode ? 'Edit' : 'Preview'}
                </Button>
              </div>
            </div>

            {!isPreviewMode && (
              <>
                {/* Toolbar */}
                <div className="flex flex-wrap gap-1 p-2 border border-gray-200 dark:border-gray-700 rounded-t-md bg-gray-50 dark:bg-gray-800">
                  <ToolbarButton onClick={() => handleToolbarAction('heading1')} icon={Heading1} tooltip="Heading 1" />
                  <ToolbarButton onClick={() => handleToolbarAction('heading2')} icon={Heading2} tooltip="Heading 2" />
                  <ToolbarButton onClick={() => handleToolbarAction('heading3')} icon={Heading3} tooltip="Heading 3" />
                  <div className="w-px h-6 bg-gray-300 dark:bg-gray-600 mx-1" />
                  <ToolbarButton onClick={() => handleToolbarAction('bold')} icon={Bold} tooltip="Bold" />
                  <ToolbarButton onClick={() => handleToolbarAction('italic')} icon={Italic} tooltip="Italic" />
                  <ToolbarButton onClick={() => handleToolbarAction('underline')} icon={Underline} tooltip="Underline" />
                  <div className="w-px h-6 bg-gray-300 dark:bg-gray-600 mx-1" />
                  <ToolbarButton onClick={() => handleToolbarAction('list')} icon={List} tooltip="Bullet List" />
                  <ToolbarButton onClick={() => handleToolbarAction('orderedList')} icon={ListOrdered} tooltip="Numbered List" />
                  <ToolbarButton onClick={() => handleToolbarAction('quote')} icon={Quote} tooltip="Quote" />
                  <div className="w-px h-6 bg-gray-300 dark:bg-gray-600 mx-1" />
                  <ToolbarButton onClick={() => handleToolbarAction('link')} icon={Link2} tooltip="Link" />
                  <ToolbarButton onClick={() => handleToolbarAction('code')} icon={Code} tooltip="Code" />
                </div>

                {/* Content Textarea */}
                <Textarea
                  ref={contentRef}
                  placeholder="Start writing your note..."
                  value={content}
                  onChange={handleContentChange}
                  className={`min-h-64 rounded-t-none ${errors.content ? 'border-red-500' : ''}`}
                  rows={12}
                />
              </>
            )}

            {isPreviewMode && (
              <div className="min-h-64 p-4 border border-gray-200 dark:border-gray-700 rounded-md bg-white dark:bg-gray-900">
                <div 
                  className="prose max-w-none dark:prose-invert"
                  dangerouslySetInnerHTML={{ __html: formatMarkdownContent(content || 'No content to preview...') }}
                />
              </div>
            )}

            {errors.content && (
              <p className="text-sm text-red-500">{errors.content.message}</p>
            )}
          </div>

          {/* Save indicator */}
          {isDirty && (
            <div className="flex items-center gap-2 text-sm text-amber-600 dark:text-amber-400">
              <div className="w-2 h-2 bg-amber-500 rounded-full animate-pulse" />
              You have unsaved changes
            </div>
          )}
        </CardContent>

        <CardFooter className="flex gap-2">
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            disabled={isSubmitting || isLoading}
          >
            <X className="h-4 w-4 mr-2" />
            Cancel
          </Button>
          <Button
            type="submit"
            disabled={isSubmitting || isLoading}
          >
            <Save className="h-4 w-4 mr-2" />
            {isSubmitting || isLoading
              ? 'Saving...'
              : mode === 'create'
                ? 'Create Note'
                : 'Save Changes'
            }
          </Button>
        </CardFooter>
      </form>
    </Card>
  );
};

export default NoteEditor;

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogTrigger } from '@/components/ui/dialog';
import { 
  Search, Plus, Folder, FolderOpen, FileText, Edit, Trash2, 
  ChevronRight, ChevronDown, MoreHorizontal, Filter, SortAsc
} from 'lucide-react';
import { TreeView } from '@/components/pkm/TreeView';
import { ProjectForm } from '@/components/forms/ProjectForm';
import { NoteEditor } from '@/components/features/NoteEditor';
import { Project, ProjectNode, ProjectCreate, ProjectUpdate } from '@/types/project';
import { Note, NoteCreate } from '@/types/note';
import { useProjectsStore } from '@/lib/store/projects';
import { apiClient } from '@/lib/api/client';

interface ProjectTreeProps {
  onSelectProject?: (project: Project) => void;
  onSelectNote?: (note: Note) => void;
  selectedProjectId?: string;
  selectedNoteId?: string;
  showNotes?: boolean;
  className?: string;
}

interface ProjectTreeItemProps {
  project: Project;
  level: number;
  isExpanded: boolean;
  onToggleExpand: (projectId: string) => void;
  onSelectProject: (project: Project) => void;
  onEditProject: (project: Project) => void;
  onDeleteProject: (project: Project) => void;
  onCreateSubproject: (parentProject: Project) => void;
  onCreateNote: (project: Project) => void;
  selectedProjectId?: string;
  selectedNoteId?: string;
  showNotes: boolean;
  notes: Note[];
  onSelectNote: (note: Note) => void;
}

const ProjectTreeItem: React.FC<ProjectTreeItemProps> = ({
  project,
  level,
  isExpanded,
  onToggleExpand,
  onSelectProject,
  onEditProject,
  onDeleteProject,
  onCreateSubproject,
  onCreateNote,
  selectedProjectId,
  selectedNoteId,
  showNotes,
  notes,
  onSelectNote
}) => {
  const [isHovered, setIsHovered] = useState(false);
  const projectNotes = notes.filter(note => note.project_id === project.id);
  const hasSubprojects = project.children && project.children.length > 0;
  const hasContent = hasSubprojects || (showNotes && projectNotes.length > 0);
  const isSelected = selectedProjectId === project.id;

  const handleToggle = () => {
    if (hasContent) {
      onToggleExpand(project.id);
    }
  };

  return (
    <div className="select-none">
      {/* Project Item */}
      <div
        className={`
          flex items-center py-2 px-2 rounded-md cursor-pointer group
          hover:bg-gray-100 dark:hover:bg-gray-800
          ${isSelected ? 'bg-blue-100 dark:bg-blue-900 border-l-4 border-blue-500' : ''}
        `}
        style={{ paddingLeft: `${level * 16 + 8}px` }}
        onClick={() => onSelectProject(project)}
        onMouseEnter={() => setIsHovered(true)}
        onMouseLeave={() => setIsHovered(false)}
      >
        {/* Expand/Collapse Button */}
        <Button
          variant="ghost"
          size="sm"
          className="h-6 w-6 p-0 mr-2"
          onClick={(e) => {
            e.stopPropagation();
            handleToggle();
          }}
        >
          {hasContent ? (
            isExpanded ? (
              <ChevronDown className="h-4 w-4" />
            ) : (
              <ChevronRight className="h-4 w-4" />
            )
          ) : (
            <div className="h-4 w-4" />
          )}
        </Button>

        {/* Folder Icon */}
        <div className="mr-2">
          {hasSubprojects ? (
            isExpanded ? (
              <FolderOpen className="h-4 w-4 text-blue-600" />
            ) : (
              <Folder className="h-4 w-4 text-blue-600" />
            )
          ) : (
            <Folder className="h-4 w-4 text-gray-500" />
          )}
        </div>

        {/* Project Name */}
        <span className="flex-1 text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
          {project.name}
        </span>

        {/* Note Count */}
        {showNotes && projectNotes.length > 0 && (
          <span className="text-xs text-gray-500 bg-gray-200 dark:bg-gray-700 px-2 py-1 rounded-full mr-2">
            {projectNotes.length}
          </span>
        )}

        {/* Action Buttons */}
        {(isHovered || isSelected) && (
          <div className="flex items-center space-x-1 opacity-100 group-hover:opacity-100">
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={(e) => {
                e.stopPropagation();
                onCreateNote(project);
              }}
              title="Add note"
            >
              <FileText className="h-3 w-3" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={(e) => {
                e.stopPropagation();
                onCreateSubproject(project);
              }}
              title="Add subproject"
            >
              <Plus className="h-3 w-3" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0"
              onClick={(e) => {
                e.stopPropagation();
                onEditProject(project);
              }}
              title="Edit project"
            >
              <Edit className="h-3 w-3" />
            </Button>
            <Button
              variant="ghost"
              size="sm"
              className="h-6 w-6 p-0 text-red-600 hover:text-red-700"
              onClick={(e) => {
                e.stopPropagation();
                onDeleteProject(project);
              }}
              title="Delete project"
            >
              <Trash2 className="h-3 w-3" />
            </Button>
          </div>
        )}
      </div>

      {/* Expanded Content */}
      {isExpanded && hasContent && (
        <div>
          {/* Subprojects */}
          {project.children?.map((child) => (
            <ProjectTreeItem
              key={child.id}
              project={child}
              level={level + 1}
              isExpanded={isExpanded}
              onToggleExpand={onToggleExpand}
              onSelectProject={onSelectProject}
              onEditProject={onEditProject}
              onDeleteProject={onDeleteProject}
              onCreateSubproject={onCreateSubproject}
              onCreateNote={onCreateNote}
              selectedProjectId={selectedProjectId}
              selectedNoteId={selectedNoteId}
              showNotes={showNotes}
              notes={notes}
              onSelectNote={onSelectNote}
            />
          ))}

          {/* Project Notes */}
          {showNotes && projectNotes.map((note) => (
            <div
              key={note.id}
              className={`
                flex items-center py-2 px-2 rounded-md cursor-pointer
                hover:bg-gray-50 dark:hover:bg-gray-700
                ${selectedNoteId === note.id ? 'bg-green-100 dark:bg-green-900 border-l-4 border-green-500' : ''}
              `}
              style={{ paddingLeft: `${(level + 1) * 16 + 32}px` }}
              onClick={() => onSelectNote(note)}
            >
              <FileText className="h-4 w-4 text-green-600 mr-2" />
              <span className="flex-1 text-sm text-gray-700 dark:text-gray-300 truncate">
                {note.title || 'Untitled Note'}
              </span>
              <span className="text-xs text-gray-400 ml-2">
                {note.note_type}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export const ProjectTree: React.FC<ProjectTreeProps> = ({
  onSelectProject,
  onSelectNote,
  selectedProjectId,
  selectedNoteId,
  showNotes = true,
  className = ''
}) => {
  const { projects, loading, loadProjects } = useProjectsStore();
  const [expandedProjects, setExpandedProjects] = useState<Set<string>>(new Set());
  const [searchTerm, setSearchTerm] = useState('');
  const [notes, setNotes] = useState<Note[]>([]);
  const [isCreateProjectOpen, setIsCreateProjectOpen] = useState(false);
  const [isCreateNoteOpen, setIsCreateNoteOpen] = useState(false);
  const [editingProject, setEditingProject] = useState<Project | null>(null);
  const [parentForNewProject, setParentForNewProject] = useState<Project | null>(null);
  const [projectForNewNote, setProjectForNewNote] = useState<Project | null>(null);

  useEffect(() => {
    loadProjects();
    if (showNotes) {
      loadNotes();
    }
  }, [loadProjects, showNotes]);

  const loadNotes = async () => {
    try {
      const response = await apiClient.get('/v1/notes/?limit=1000');
      setNotes(response.items || []);
    } catch (error) {
      console.error('Failed to load notes:', error);
    }
  };

  const handleToggleExpand = (projectId: string) => {
    setExpandedProjects(prev => {
      const newSet = new Set(prev);
      if (newSet.has(projectId)) {
        newSet.delete(projectId);
      } else {
        newSet.add(projectId);
      }
      return newSet;
    });
  };

  const handleCreateProject = async (data: ProjectCreate) => {
    try {
      await apiClient.post('/v1/projects/', data);
      await loadProjects();
      setIsCreateProjectOpen(false);
      setParentForNewProject(null);
    } catch (error) {
      console.error('Failed to create project:', error);
    }
  };

  const handleUpdateProject = async (data: ProjectUpdate) => {
    if (!editingProject) return;

    try {
      await apiClient.put(`/v1/projects/${editingProject.id}`, data);
      await loadProjects();
      setEditingProject(null);
    } catch (error) {
      console.error('Failed to update project:', error);
    }
  };

  const handleDeleteProject = async (project: Project) => {
    if (window.confirm(`Are you sure you want to delete "${project.name}"? This action cannot be undone.`)) {
      try {
        await apiClient.delete(`/v1/projects/${project.id}`);
        await loadProjects();
      } catch (error) {
        console.error('Failed to delete project:', error);
      }
    }
  };

  const handleCreateNote = async (data: NoteCreate) => {
    try {
      await apiClient.post('/v1/notes/', data);
      await loadNotes();
      setIsCreateNoteOpen(false);
      setProjectForNewNote(null);
    } catch (error) {
      console.error('Failed to create note:', error);
    }
  };

  const buildProjectTree = (projects: Project[]): Project[] => {
    const projectMap = new Map<string, Project>();
    const rootProjects: Project[] = [];

    // First pass: create map and initialize children arrays
    projects.forEach(project => {
      projectMap.set(project.id, { ...project, children: [] });
    });

    // Second pass: build tree structure
    projects.forEach(project => {
      const projectWithChildren = projectMap.get(project.id)!;

      if (project.parent_project_id && projectMap.has(project.parent_project_id)) {
        const parent = projectMap.get(project.parent_project_id)!;
        parent.children!.push(projectWithChildren);
      } else {
        rootProjects.push(projectWithChildren);
      }
    });

    return rootProjects;
  };

  const filterProjects = (projects: Project[], searchTerm: string): Project[] => {
    if (!searchTerm) return projects;

    const filtered: Project[] = [];
    const searchLower = searchTerm.toLowerCase();

    const checkProject = (project: Project): boolean => {
      const matchesName = project.name.toLowerCase().includes(searchLower);
      const matchesDescription = project.description?.toLowerCase().includes(searchLower) || false;
      const childrenMatch = project.children?.some(checkProject) || false;

      if (matchesName || matchesDescription || childrenMatch) {
        const filteredChildren = project.children?.filter(checkProject) || [];
        filtered.push({ ...project, children: filteredChildren });
        return true;
      }

      return false;
    };

    projects.forEach(checkProject);
    return filtered;
  };

  const projectTree = buildProjectTree(projects);
  const filteredProjects = filterProjects(projectTree, searchTerm);

  if (loading) {
    return (
      <Card className={className}>
        <CardContent className="p-6">
          <div className="flex items-center justify-center">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className={className}>
      <CardHeader className="pb-4">
        <div className="flex items-center justify-between">
          <CardTitle className="flex items-center gap-2">
            <Folder className="h-5 w-5" />
            Projects
          </CardTitle>
          <Button
            size="sm"
            onClick={() => setIsCreateProjectOpen(true)}
          >
            <Plus className="h-4 w-4 mr-2" />
            New Project
          </Button>
        </div>

        {/* Search */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
          <Input
            placeholder="Search projects..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="pl-10"
          />
        </div>
      </CardHeader>

      <CardContent className="pt-0">
        {filteredProjects.length === 0 ? (
          <div className="text-center py-8">
            <Folder className="h-12 w-12 text-gray-400 mx-auto mb-4" />
            <p className="text-gray-500 dark:text-gray-400">
              {searchTerm ? 'No projects match your search' : 'No projects found'}
            </p>
            {!searchTerm && (
              <Button
                className="mt-4"
                onClick={() => setIsCreateProjectOpen(true)}
              >
                <Plus className="mr-2 h-4 w-4" />
                Create Your First Project
              </Button>
            )}
          </div>
        ) : (
          <div className="space-y-1">
            {filteredProjects.map((project) => (
              <ProjectTreeItem
                key={project.id}
                project={project}
                level={0}
                isExpanded={expandedProjects.has(project.id)}
                onToggleExpand={handleToggleExpand}
                onSelectProject={(p) => onSelectProject?.(p)}
                onEditProject={setEditingProject}
                onDeleteProject={handleDeleteProject}
                onCreateSubproject={(parent) => {
                  setParentForNewProject(parent);
                  setIsCreateProjectOpen(true);
                }}
                onCreateNote={(project) => {
                  setProjectForNewNote(project);
                  setIsCreateNoteOpen(true);
                }}
                selectedProjectId={selectedProjectId}
                selectedNoteId={selectedNoteId}
                showNotes={showNotes}
                notes={notes}
                onSelectNote={(note) => onSelectNote?.(note)}
              />
            ))}
          </div>
        )}
      </CardContent>

      {/* Create Project Dialog */}
      <Dialog open={isCreateProjectOpen} onOpenChange={setIsCreateProjectOpen}>
        <DialogContent>
          <ProjectForm
            mode="create"
            parentProject={parentForNewProject || undefined}
            onSubmit={handleCreateProject}
            onCancel={() => {
              setIsCreateProjectOpen(false);
              setParentForNewProject(null);
            }}
          />
        </DialogContent>
      </Dialog>

      {/* Edit Project Dialog */}
      <Dialog open={!!editingProject} onOpenChange={(open) => !open && setEditingProject(null)}>
        <DialogContent>
          {editingProject && (
            <ProjectForm
              mode="edit"
              project={editingProject}
              onSubmit={handleUpdateProject}
              onCancel={() => setEditingProject(null)}
            />
          )}
        </DialogContent>
      </Dialog>

      {/* Create Note Dialog */}
      <Dialog open={isCreateNoteOpen} onOpenChange={setIsCreateNoteOpen}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          {projectForNewNote && (
            <NoteEditor
              mode="create"
              projects={projects}
              defaultProjectId={projectForNewNote.id}
              onSave={handleCreateNote}
              onCancel={() => {
                setIsCreateNoteOpen(false);
                setProjectForNewNote(null);
              }}
            />
          )}
        </DialogContent>
      </Dialog>
    </Card>
  );
};

